// Data model and helpers for LayoutPanels.astro: one or more grids of cell values (offsets,
// coordinates, XOR results, letters, thread ids...) shown behind tabs. A grid is plain data, so
// layouts whose strides are not integers (coordinate strides e0/e1, F2 swizzles) can be drawn too.
// The figure data itself is generated by a script and checked against PyCuTe (see
// cuteAlgebraFigures.ts).

export interface LayoutPanel {
	/** Tab label; needed when a figure has more than one panel. */
	tab?: string;
	/** Line under the grid, usually `name = layout`. */
	caption: string;
	/** Header text per row and per column (often nested coordinates such as "(1,0)"). */
	rowHeads: string[];
	colHeads: string[];
	/** Big text in each cell, rows × columns. */
	cells: string[][];
	/** Colour group per cell. Cells in one group share a hue and light up together on hover.
	 *  `null` draws the cell dimmed (not selected / not accessed). Without groups, cells are
	 *  tinted by their numeric value mod 8. */
	groups?: (string | null)[][];
	/** Small grey text under the value. */
	subs?: string[][];
	/** Hover readout per cell, e.g. "(1,2) → ((1,0),(1,0)) → 26". */
	tips?: string[][];
	/** Sentence shown in the readout line before anything is hovered. */
	note?: string;
	/** Optional axis titles. */
	rowTitle?: string;
	colTitle?: string;
}

export type CellSize = "normal" | "small" | "tiny";

// Approximate CSS metrics of each cell size in px (see LayoutPanels.astro): minimum cell width,
// horizontal padding + border + spacing, and the monospace character widths of values, sub-labels
// and headers (0.6 em per character).
const METRICS: Record<
	CellSize,
	{ min: number; pad: number; value: number; sub: number; head: number }
> = {
	normal: { min: 41.6, pad: 14.6, value: 7.9, sub: 5.8, head: 6.3 },
	small: { min: 31.2, pad: 9.8, value: 6.5, sub: 4.8, head: 6.3 },
	tiny: { min: 16, pad: 4.6, value: 5.4, sub: 4.8, head: 5.3 },
};

/** Width in px a panel's grid needs at a given cell size, from its longest texts per column. */
export function estimateWidth(panel: LayoutPanel, size: CellSize): number {
	const m = METRICS[size];
	const longest = (texts: (string | undefined)[]) =>
		Math.max(0, ...texts.map((t) => (t ?? "").length));
	let width = longest(panel.rowHeads) * m.head + m.pad;
	panel.colHeads.forEach((head, j) => {
		const value = longest(panel.cells.map((r) => r[j])) * m.value;
		const sub = longest((panel.subs ?? []).map((r) => r[j])) * m.sub;
		const cell = Math.max(m.min, value, sub) + m.pad;
		width += Math.max(cell, head.length * m.head + 6);
	});
	return width;
}

/** The largest cell size whose grid fits the text column (about 680 px), else the smallest. */
export function cellSize(panel: LayoutPanel, available = 680): CellSize {
	for (const size of ["normal", "small"] as const)
		if (estimateWidth(panel, size) <= available) return size;
	return "tiny";
}

/** Golden-angle hue steps keep neighbouring groups distinct (same rule as Matrix2D). */
export function hueOf(k: number): number {
	return (25 + k * 137.508) % 360;
}

/** Index of every non-null group in first-seen (row-major) order. */
export function groupIndex(panel: LayoutPanel): Map<string, number> {
	const keys = new Map<string, number>();
	for (const row of panel.groups ?? [])
		for (const g of row)
			if (g !== null && g !== undefined && !keys.has(g)) keys.set(g, keys.size);
	return keys;
}

/** Hue for one cell, or null for a dimmed cell. */
export function cellHue(
	panel: LayoutPanel,
	keys: Map<string, number>,
	i: number,
	j: number,
): number | null {
	if (panel.groups) {
		const g = panel.groups[i]?.[j];
		if (g === null || g === undefined) return null;
		return hueOf(keys.get(g) ?? 0);
	}
	const v = Number(panel.cells[i][j]);
	return hueOf(
		Number.isFinite(v) ? ((v % 8) + 8) % 8 : i * panel.colHeads.length + j,
	);
}

/** Problems with a panel's dimensions; an empty list means the panel can be drawn. */
export function validatePanel(panel: LayoutPanel): string[] {
	const rows = panel.rowHeads.length;
	const cols = panel.colHeads.length;
	const errs: string[] = [];
	const checkGrid = (name: string, grid: unknown[][] | undefined) => {
		if (!grid) return;
		if (grid.length !== rows)
			errs.push(`${name} has ${grid.length} rows, expected ${rows}`);
		grid.forEach((r, i) => {
			if (r.length !== cols)
				errs.push(`${name}[${i}] has ${r.length} columns, expected ${cols}`);
		});
	};
	checkGrid("cells", panel.cells);
	checkGrid("groups", panel.groups);
	checkGrid("subs", panel.subs);
	checkGrid("tips", panel.tips);
	return errs;
}

/** Cell size per panel, shared by panels with the same grid dimensions so tabs do not jump. */
export function sharedSizes(panels: LayoutPanel[]): CellSize[] {
	const order: CellSize[] = ["normal", "small", "tiny"];
	const dims = (p: LayoutPanel) => `${p.rowHeads.length}x${p.colHeads.length}`;
	const smallest = new Map<string, number>();
	for (const p of panels) {
		const k = order.indexOf(cellSize(p));
		smallest.set(dims(p), Math.max(smallest.get(dims(p)) ?? 0, k));
	}
	return panels.map((p) => order[smallest.get(dims(p)) ?? 0]);
}
